if.script:
// Count invalid DTEs
invalidDteCount = validationResult.invalidDteIdList.size()

// Collect unique issuers and build DTE details
issuerSet = new HashSet()
invalidDteDetailsList = []

validationResult.invalidDteIdList.eachWithIndex { invalidDteId, idx ->
    // Limit to first 10 DTEs for concise notification
    if (idx < 10) {
        def dte = ec.entity.find("mchile.dte.FiscalTaxDocument")
            .condition("fiscalTaxDocumentId", invalidDteId)
            .one()

        if (dte) {
            issuerSet.add(dte.issuerPartyId)

            // Get issuer party name
            def issuerParty = ec.entity.find("mantle.party.PartyDetail")
                .condition("partyId", dte.issuerPartyId)
                .one()
            String issuerName = issuerParty?.organizationName ?: issuerParty?.pseudoId ?: dte.issuerPartyId

            // Truncate validation error to first 200 characters
            String validationError = validationResult.validationErrorMap[invalidDteId]
            if (validationError && validationError.length() > 200) {
                validationError = validationError.substring(0, 200) + "..."
            }

            invalidDteDetailsList.add([
                fiscalTaxDocumentId: invalidDteId,
                issuerPartyId: dte.issuerPartyId,
                issuerName: issuerName,
                validationError: validationError
            ])
        }
    } else {
        // Still need to collect issuer for count
        def dte = ec.entity.find("mchile.dte.FiscalTaxDocument")
            .condition("fiscalTaxDocumentId", invalidDteId)
            .one()
        if (dte) {
            issuerSet.add(dte.issuerPartyId)
        }
    }
}

// Build notification message map
messageMap = [
    invalidDteCount: invalidDteCount,
    issuerCount: issuerSet.size(),
    invalidDteDetails: invalidDteDetailsList,
    tipo: tipo,
    timestamp: ec.l10n.format(ec.user.nowTimestamp, "yyyy-MM-dd HH:mm:ss")
]

// Send notification
try {
    ec.notification()
        .topic("DTE_SCHEMA_VALIDATION_FAILURE")
        .message(messageMap)
        .send()
    ec.logger.info("Notification sent for ${invalidDteCount} invalid DTE(s) from ${issuerSet.size()} issuer(s)")
} catch (Exception e) {
    ec.logger.warn("Failed to send notification for invalid DTEs: ${e.message}")
}

actions.script:
import cl.moit.dte.MoquiDTEUtils

org.moqui.context.ExecutionContext ec = context.ec
org.w3c.dom.Document doc = null
try {
    doc = MoquiDTEUtils.parseDocument(contentBytes)
} catch (Exception e) {
    ec.logger.error("Parsing document ${receivedFileName} of message ${messageId}: ${e.toString()}")
    return
}
firstTag = doc.getDocumentElement().getNodeName()
groovy.util.Node envio = MoquiDTEUtils.dom2GroovyNode(doc)
generalSignedXPath = null
internalSignedXPath = null
generalDateXPath = null
envioTypeEnumId = null
internalId = null
if (firstTag == 'EnvioDTE') {
    /*
    internalSignedXPath = "/sii:EnvioDTE/sii:SetDTE/sii:DTE/sii:Documento"
    internalDateXPath = "./sii:Encabezado/sii:IdDoc/sii:FchEmis/text()"
     */
    envioTypeEnumId = 'Ftde-EnvioDte'
    processingParameters = groovy.json.JsonOutput.toJson([createUnknownIssuer:createUnknownIssuer, requireIssuerInternalOrg:requireIssuerInternalOrg,
                                                          createUnknownReceiver:createUnknownReceiver, requireReceiverInternalOrg:requireReceiverInternalOrg,
                                                          sentAuthStatusId:sentAuthStatusId])
    setDte = envio.SetDTE
    caratula = setDte.Caratula
    rutEmisorCaratula = caratula.RutEmisor.text()
    rutReceptorCaratula = caratula.RutReceptor.text()
    fechaEnvio = ec.l10n.parseTimestamp(caratula.TmstFirmaEnv.text(), "yyyy-MM-dd'T'HH:mm:ss")
    internalId = setDte.'@ID'.text()
} else if (firstTag == 'RESULTADO_ENVIO') {
    // Envío recibido en SII
    envioTypeEnumId = 'Ftde-ResultadoEnvio'
    identificacion = envio.IDENTIFICACION
    rutReceptorCaratula = identificacion.RUTEMISOR.text()
    rutEmisorCaratula = "60803000-K" // Rut del SII
    fechaEnvio = ec.l10n.parseTimestamp(identificacion.TMSTRECEPCION.text(), "dd/MM/yyyy HH:mm:ss")
    internalId = identificacion.TRACKID.text()
} else if (firstTag == 'EnvioRecibos') {
    // Recibos: aceptacion de los servicios y/o mercaderia para efecto de merito ejecutivo
    envioTypeEnumId = 'Ftde-EnvioRecibos'
    setRecibos = envio.SetRecibos
    caratula = setRecibos.Caratula
    rutEmisorCaratula = caratula.RutResponde.text()
    rutReceptorCaratula = caratula.RutRecibe.text()
    fechaEnvio = ec.l10n.parseTimestamp(caratula.TmstFirmaEnv.text(), "yyyy-MM-dd'T'HH:mm:ss")
    internalId = setRecibos.'@ID'.text()
    /*
    generalSignedXPath = "/sii:EnvioRecibos/sii:SetRecibos"
    generalDateXPath = "./sii:Caratula/sii:TmstFirmaEnv/text()"
     */
} else if (firstTag == 'RespuestaDTE') {
    // Recepción de los DTE
    envioTypeEnumId = 'Ftde-RespuestaDte'
    resultado = envio.Resultado
    caratula = resultado.Caratula
    rutEmisorCaratula = caratula.RutResponde.text()
    rutReceptorCaratula = caratula.RutRecibe.text()
    fechaEnvio = ec.l10n.parseTimestamp(caratula.TmstFirmaResp.text(), "yyyy-MM-dd'T'HH:mm:ss")
    internalId = resultado.'@ID'.text()
    // Si es respuesta a un envío: RespuestaDTE/Resultado/RecepcionEnvio
    // Si es respuesta a un DTE en particular: RespuestaDTE/Resultado/ResultadoDTE
    /*
    generalSignedXPath = "/sii:RespuestaDTE/sii:Resultado"
    generalDateXPath = "./sii:Caratula/sii:TmstFirmaResp/text()"
     */
} else if (firstTag == 'ResultadoConsumoFolios') {
    // Consumo Folios recibido en SII
    envioTypeEnumId = 'Ftde-ResultadoConsumoFolios'
    identificacion = envio.IDENTIFICACION
    rutReceptorCaratula = identificacion.RUTEMISOR.text()
    rutEmisorCaratula = "60803000-K" // Rut del SII
    fechaEnvio = ec.l10n.parseTimestamp(identificacion.TMSTRECEPCION.text(), "dd/MM/yyyy HH:mm:ss")
    internalId = identificacion.TRACKID.text()
} else if (firstTag == 'DTE' && storeDteXmlWithoutEnvio) {
    envioTypeEnumId = 'Ftde-PlainDte'
    documento = envio.Documento
    rutReceptorCaratula = documento.Encabezado.Receptor.RUTRecep.text()
    rutEmisorCaratula = documento.Encabezado.Emisor.RUTEmisor.text()
    fechaEnvio = ec.user.nowTimestamp
    internalId = documento.'@ID'.text()
} else if (firstTag == 'SetDTE' && storeDteXmlWithoutEnvio) {
    dteNodeList = doc.getDocumentElement().getElementsByTagName("DTE")
    if (dteNodeList.length < 1) {
        ec.logger.error("Content with filename ${fileName} for email ${messageId}, firstTag: ${firstTag}, no DTE child found")
        return
    }
    envioTypeEnumId = 'Ftde-PlainDte'
    documento = envio.DTE.Documento
    rutReceptorCaratula = documento.Encabezado.Receptor.RUTRecep.text()
    rutEmisorCaratula = documento.Encabezado.Emisor.RUTEmisor.text()
    fechaEnvio = ec.user.nowTimestamp
    internalId = documento.'@ID'.text()
} else {
    ec.logger.error("Unrecognized content with filename ${fileName} for email ${messageId}, firstTag: ${firstTag}")
    return
}
/*
if (generalSignedXPath)
    if (!MoquiDTEUtils.verifySignature(doc, generalSignedXPath, generalDateXPath))
        ec.message.addError("No se verifica firma en ${generalSignedXPath}")
if (internalSignedXPath)
    if (!MoquiDTEUtils.verifySignature(doc, internalSignedXPath, internalDateXPath))
        ec.message.addError("No se verifica firma en ${internalSignedXPath}")
 */
envioId = ec.service.sync().name("create#mchile.dte.DteEnvio").parameters([envioTypeEnumId:envioTypeEnumId, emailMessageId:emailMessageId, statusId:'Ftde-Received',
                                                                           rutEmisor:rutEmisorCaratula, rutReceptor:rutReceptorCaratula, fechaEnvio:fechaEnvio, fechaRegistro:ec.user.nowTimestamp,
                                                                           internalId:internalId, processingParameters:processingParameters]).call().envioId
envEv = ec.entity.find("moqui.basic.Enumeration").condition("enumId", envioTypeEnumId).one()
documentLocation ="dbresource://moit/erp/dte/${envEv.enumCode}/${rutEmisorCaratula}/${rutEmisorCaratula}-${envioId}.xml"
ec.resource.getLocationReference(documentLocation).putBytes(contentBytes)
ec.service.sync().name("update#mchile.dte.DteEnvio").parameters([envioId:envioId, documentLocation:documentLocation, fileName:fileName]).call()

Calendar cal = Calendar.instance cal.setTimeInMillis(ec.user.nowTimestamp.time) cal.set(Calendar.HOUR_OF_DAY, 23) cal.set(Calendar.MINUTE, 59) cal.set(Calendar.SECOND, 59) cal.set(Calendar.MILLISECOND, 999) todayEnd = new Timestamp(cal.timeInMillis)
cal.add(Calendar.DAY_OF_MONTH, -lookbackDays) cal.set(Calendar.HOUR_OF_DAY, 0) cal.set(Calendar.MINUTE, 0) cal.set(Calendar.SECOND, 0) cal.set(Calendar.MILLISECOND, 0) lookbackStart = new Timestamp(cal.timeInMillis)
// Calculate 3 days ago for stuck envio detection cal.setTimeInMillis(ec.user.nowTimestamp.time) cal.add(Calendar.DAY_OF_MONTH, -3) threeDaysAgo = new Timestamp(cal.timeInMillis)

iterate.script:
// Calculate days since last attempt
long daysDiff = (ec.user.nowTimestamp.time - envio.lastAttempt.time) / (24 * 60 * 60 * 1000)

// CENTRALIZED CLASSIFICATION LOGIC: Determine if this is a warning or error
boolean isWarning = false

// WARNINGS: 
// 1. Status ProcessedWithDiscrepancy
// 2. Status Created or Received with >= 3 days since last attempt
if (envio.statusId == 'Ftde-ProcessedWithDiscrepancy' ||
    (envio.statusId in ['Ftde-Created', 'Ftde-Received'] && daysDiff >= 3)) {
    isWarning = true
}

// ERRORS: All other failure conditions (default)

Map envioInfo = [
    envioId: envio.envioId, 
    statusId: envio.statusId, 
    internalId: envio.internalId,
    envioTypeEnumId: envio.envioTypeEnumId,
    daysSinceLastAttempt: daysDiff as Integer,
    severity: isWarning ? 'warning' : 'error'
]

// Add to main list
directionData.envioList.add(envioInfo)

// Add to severity-specific lists and update counts
if (isWarning) {
    directionData.warningEnvioList.add(envioInfo)
    directionData.warningCount = directionData.warningCount + 1
} else {
    directionData.errorEnvioList.add(envioInfo)
    directionData.errorCount = directionData.errorCount + 1
}

// Fill missing days
cal = Calendar.instance
cal.setTimeInMillis(lookbackStart.time)
Map sortedDailyCounts = new TreeMap()

for (int i = 0; i <= lookbackDays; i++) {
    String dayKey = ec.l10n.format(new Timestamp(cal.timeInMillis), 'yyyy-MM-dd')
    sortedDailyCounts[dayKey] = partyData[direction].dailyCounts[dayKey] ?: 0
    cal.add(Calendar.DAY_OF_MONTH, 1)
}

partyData[direction].dailyCounts = sortedDailyCounts
